{
  "@context": "https://schema.org",
  "@type": "WebApplication",
  "name": "Kalkulator Statistik K3 Online Indonesia",
  "url": "https://wahanatotalita.com/tools/kalkulator-k3/",
  "description": "Perhitungan statistik K3 resmi Kemnaker RI (Kepmenaker 372/1989) & OSHA: FR, SR, IR, LTIFR, Safe T-Score, dan Piramida Heinrich.",
  "applicationCategory": "BusinessApplication",
  "operatingSystem": "All",
  "offers": { "@type": "Offer", "price": "0", "priceCurrency": "IDR" }
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Apa perbedaan standar pengali 1.000.000 jam kerja dan 200.000 jam kerja?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Standar 1.000.000 jam kerja adalah standar resmi Depnaker/Kemnaker RI berdasarkan Kepmenaker No. KEP.372/MEN/1989 dan ILO, mewakili sekitar 500 pekerja penuh waktu selama 1 tahun. Sedangkan standar 200.000 jam kerja mengacu pada US OSHA (Occupational Safety and Health Administration), mewakili 100 pekerja penuh waktu selama 1 tahun (100 pekerja x 40 jam/minggu x 50 minggu kerja)."
      }
    },
    {
      "@type": "Question",
      "name": "Bagaimana cara membaca nilai Safe T-Score?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Safe T-Score digunakan untuk membandingkan kinerja K3 periode saat ini dengan periode sebelumnya. Jika nilai Safe T-Score di antara -2.00 hingga +2.00, perbedaannya dianggap fluktuasi normal. Jika skor lebih kecil dari -2.00, performa K3 membaik secara signifikan. Jika skor lebih besar dari +2.00, performa K3 memburuk secara signifikan dan memerlukan investigasi akar penyebab segera."
      }
    },
    {
      "@type": "Question",
      "name": "Berapa hari kerja hilang yang dihitung untuk kasus kecelakaan fatal atau cacat tetap total?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Sesuai Kepmenaker KEP.372/MEN/1989 dan ANSI Z16.1, untuk kasus kecelakaan fatal (kematian) dan cacat total permanen (kehilangan fungsi kedua mata, kedua tangan, atau kelumpuhan total), beban hari kerja hilang yang dibebankan adalah 6.000 hari kerja (man-days lost)."
      }
    }
  ]
}

inline_styles:
:root {
  --navy-dark: #071524;
  --navy: #0D233A;
  --navy-light: #183654;
  --orange: #E8611A;
  --orange-hover: #cf5213;
  --orange-light: #fff2ea;
  --slate-50: #F8FAFC;
  --slate-100: #F1F5F9;
  --slate-200: #E2E8F0;
  --slate-300: #CBD5E1;
  --slate-600: #475569;
  --slate-700: #334155;
  --slate-900: #0F172A;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 2px 8px rgba(13,35,58,0.06);
  --shadow-md: 0 8px 24px rgba(13,35,58,0.1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Source Sans 3', system-ui, -apple-system, sans-serif;
  background: var(--slate-50);
  color: var(--slate-900);
  line-height: 1.6;
}
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* HERO */
.calc-hero {
  background: linear-gradient(135deg, #071524 0%, #0D233A 60%, #183654 100%);
  color: #fff;
  padding: 60px 0 46px;
  position: relative;
  overflow: hidden;
  border-bottom: 3px solid var(--orange);
}
.calc-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 36px 36px;
  pointer-events: none;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(232, 97, 26, 0.18);
  border: 1px solid rgba(232, 97, 26, 0.4);
  padding: 6px 14px;
  border-radius: 999px;
  color: #FFA573;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 14px;
}
.calc-hero h1 {
  font-family: 'Lexend', sans-serif;
  font-size: clamp(1.8rem, 3.6vw, 2.8rem);
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 12px;
}
.calc-hero h1 span { color: var(--orange); }
.calc-hero p {
  color: #CBD5E1;
  font-size: 1.05rem;
  max-width: 760px;
  margin-bottom: 24px;
}
.hero-tags { display: flex; flex-wrap: wrap; gap: 8px; }
.hero-tag {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  padding: 4px 12px;
  border-radius: 6px;
  font-size: 0.82rem;
  color: #E2E8F0;
}

/* LAYOUT */
.calc-wrapper { padding: 40px 0 60px; }
.calc-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 32px;
  align-items: start;
}
@media (max-width: 992px) {
  .calc-grid { grid-template-columns: 1fr; }
}

/* CARDS */
.card-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  padding: 28px;
  margin-bottom: 28px;
}
.card-header-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px solid var(--slate-100);
  padding-bottom: 16px;
  margin-bottom: 22px;
}
.card-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--navy);
  display: flex;
  align-items: center;
  gap: 10px;
}

/* FORM STYLES */
.preset-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 20px;
}
.pill-btn {
  background: var(--slate-100);
  border: 1px solid var(--slate-200);
  padding: 6px 14px;
  border-radius: 999px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--slate-700);
  cursor: pointer;
  transition: all 0.2s;
}
.pill-btn:hover, .pill-btn.active {
  background: var(--navy);
  border-color: var(--navy);
  color: #fff;
}

.form-group-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 18px;
}
@media (max-width: 600px) {
  .form-group-grid { grid-template-columns: 1fr; }
}
.form-field { margin-bottom: 16px; }
.form-label {
  display: flex;
  justify-content: space-between;
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 6px;
}
.form-label small { color: var(--slate-600); font-weight: 400; }
.form-input {
  width: 100%;
  padding: 10px 14px;
  border: 1.5px solid var(--slate-200);
  border-radius: var(--radius-md);
  font-size: 0.95rem;
  color: var(--slate-900);
  background: #fff;
  transition: border-color 0.2s;
}
.form-input:focus {
  outline: none;
  border-color: var(--orange);
  box-shadow: 0 0 0 3px rgba(232,97,26,0.12);
}
.unit-toggle {
  display: flex;
  background: var(--slate-100);
  padding: 4px;
  border-radius: var(--radius-md);
  margin-bottom: 20px;
}
.unit-opt {
  flex: 1;
  text-align: center;
  padding: 8px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--slate-700);
  border-radius: 8px;
  cursor: pointer;
  border: none;
  background: transparent;
  transition: all 0.2s;
}
.unit-opt.active {
  background: #fff;
  color: var(--navy);
  box-shadow: 0 2px 6px rgba(0,0,0,0.06);
}

/* RESULTS PANEL */
.result-stat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 22px;
}
.stat-card {
  background: var(--slate-50);
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  padding: 16px;
  position: relative;
  overflow: hidden;
}
.stat-card.featured {
  background: linear-gradient(145deg, #0D233A 0%, #183654 100%);
  color: #fff;
  border-color: #0D233A;
}
.stat-card.featured .stat-meta { color: #FFA573; }
.stat-card.featured .stat-val { color: #fff; }
.stat-card.featured .stat-desc { color: #CBD5E1; }
.stat-card::after {
  content: "";
  position: absolute;
  top: 0; left: 0;
  width: 4px; height: 100%;
  background: var(--orange);
}
.stat-meta {
  font-size: 0.76rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--slate-600);
  letter-spacing: 0.04em;
  margin-bottom: 4px;
}
.stat-val {
  font-family: 'Lexend', sans-serif;
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1.1;
  margin-bottom: 4px;
}
.stat-desc { font-size: 0.8rem; color: var(--slate-600); }

/* SAFE T-SCORE GAUGE */
.safe-t-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  padding: 16px;
  margin-bottom: 20px;
}
.safe-t-badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 700;
  margin-top: 6px;
}
.safe-t-good { background: #DCFCE7; color: #166534; }
.safe-t-normal { background: #FEF3C7; color: #92400E; }
.safe-t-bad { background: #FEE2E2; color: #991B1B; }

/* HEINRICH PYRAMID SVG */
.pyramid-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  padding: 18px;
  text-align: center;
  margin-bottom: 22px;
}
.pyramid-title {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 12px;
}
.pyramid-level {
  padding: 8px 12px;
  margin: 4px auto;
  border-radius: 6px;
  font-size: 0.82rem;
  font-weight: 600;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: transform 0.2s;
}
.pyr-1 { width: 45%; background: #EF4444; color: #fff; }
.pyr-2 { width: 62%; background: #F97316; color: #fff; }
.pyr-3 { width: 80%; background: #FBBF24; color: #78350F; }
.pyr-4 { width: 100%; background: #E2E8F0; color: #1E293B; }

/* ACTION BUTTONS */
.btn-row { display: flex; gap: 12px; margin-top: 14px; }
.btn-calc-action {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 18px;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 700;
  cursor: pointer;
  border: none;
  transition: all 0.2s;
  text-decoration: none;
}
.btn-primary-k3 {
  background: var(--orange);
  color: #fff;
}
.btn-primary-k3:hover {
  background: var(--orange-hover);
  color: #fff;
}
.btn-outline-k3 {
  background: #fff;
  color: var(--navy);
  border: 1.5px solid var(--slate-300);
}
.btn-outline-k3:hover {
  background: var(--slate-100);
}

/* REFERENCE & CONTENT SECTIONS */
.k3-editorial-section {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  padding: 36px;
  margin-bottom: 32px;
}
.editorial-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.45rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 16px;
  border-left: 4px solid var(--orange);
  padding-left: 14px;
}
.editorial-p {
  color: var(--slate-700);
  font-size: 0.96rem;
  line-height: 1.7;
  margin-bottom: 16px;
}
.ref-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
  margin: 20px 0;
}
.ref-table th {
  background: var(--navy);
  color: #fff;
  padding: 10px 14px;
  text-align: left;
  font-weight: 600;
}
.ref-table td {
  padding: 10px 14px;
  border-bottom: 1px solid var(--slate-200);
  color: var(--slate-700);
}
.ref-table tr:nth-child(even) td { background: var(--slate-50); }

/* FAQ ACCORDION */
.faq-box { margin-top: 20px; }
.faq-item {
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  background: #fff;
}
.faq-q {
  width: 100%;
  padding: 16px 20px;
  text-align: left;
  background: #fff;
  border: none;
  font-family: 'Lexend', sans-serif;
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--navy);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-q:hover { background: var(--slate-50); }
.faq-a {
  padding: 0 20px 18px;
  color: var(--slate-700);
  font-size: 0.92rem;
  line-height: 1.65;
  display: none;
}
.faq-item.active .faq-a { display: block; }
.faq-item.active .faq-icon { transform: rotate(180deg); }
.faq-icon { transition: transform 0.2s; font-size: 0.8rem; }

/* PRINT STYLES */
@media print {
  body { background: #fff; color: #000; }
  .calc-hero, .pill-btn, .btn-row, nav, footer, .faq-box, .unit-toggle, .form-input, .k3-editorial-section { display: none !important; }
  .calc-wrapper { padding: 0; }
  .calc-grid { display: block; }
  .card-box { border: none; box-shadow: none; padding: 0; }
  .print-header { display: block !important; border-bottom: 2px solid #000; padding-bottom: 12px; margin-bottom: 20px; }
}
.print-header { display: none; }

